item.command:
/bin/zsh -lc "cat > answer.json <<'EOF'
{
  \"registered_files\": [
    \"src/channels/audit.js\",
    \"src/channels/mail.js\"
  ],
  \"selected_file\": \"src/channels/mail.js\",
  \"selected_output\": \"mail:hi\",
  \"unknown_kind_error\": \"unknown kind\",
  \"target_depends_on_runtime_kind\": true,
  \"legacy_reachable_from_dispatch\": false
}
EOF
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { dispatch } from './src/dispatch.js';
import { registry } from './src/registry.js';
import { handle as audit } from './src/channels/audit.js';
import { handle as mail } from './src/channels/mail.js';
import { handle as legacy } from './src/channels/legacy.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), [
  'registered_files', 'selected_file', 'selected_output', 'unknown_kind_error',
  'target_depends_on_runtime_kind', 'legacy_reachable_from_dispatch'
]);
assert.deepEqual(Object.keys(registry).sort(), ['audit', 'mail']);
assert.equal(registry.audit, audit);
assert.equal(registry.mail, mail);
assert.deepEqual(answer.registered_files, ['src/channels/audit.js', 'src/channels/mail.js']);
assert.equal(answer.selected_file, 'src/channels/mail.js');
assert.equal(dispatch({ kind: 'mail', payload: ' Hi ' }), answer.selected_output);
assert.equal(dispatch({ kind: 'audit', payload: ' Hi ' }), audit(' Hi '));
for (const kind of ['legacy', 'toString', 'unknown']) {
  assert.throws(() => dispatch({ kind, payload: ' Hi ' }), error =>
    error instanceof Error && error.message === answer.unknown_kind_error);
}
assert.equal(answer.target_depends_on_runtime_kind, registry.audit "'!== registry.mail);
assert.equal(answer.legacy_reachable_from_dispatch, Object.values(registry).includes(legacy));
console.log('"'Verified answer.json against registry and dispatch behavior.');
EOF"

